 "content": "def transform(grid):
    """Copy the nonzero pattern surrounding the decorated 5 marker to the isolated 5."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(markers) < 2:
        return [row[:] for row in grid]

    def local_count(pos):
        r, c = pos
        return sum(
            1 for y in range(max(0, r - 3), min(h, r + 4))
            for x in range(max(0, c - 3), min(w, c + 4))
            if (y, x) != pos and grid[y][x] != 0
        )

    source = max(markers, key=local_count)
    target = min(markers, key=local_count)
    sr, sc = source
    tr, tc = target
    out = [row[:] for row in grid]
    out[tr][tc] = 0
    for r in range(h):
        for c in range(w):
            if (r, c) != source and grid[r][c] != 0:
                nr, nc = tr + (r - sr), tc + (c - sc)
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = grid[r][c]
    return out
